   "sintesis": "Minsa y Digesa emitieron una alerta sanitaria tras detectar la bacteria Pseudomonas aeruginosa en el agua de mesa “Manantial Adonai”. El Ministerio de Salud (Minsa) , a través de la Dirección General de Salud Ambiental e Inocuidad Alimentaria (Digesa) , ordenó el retiro inmediato del agua de mesa Manantial Adonai de cualquier establecimiento comercial tras detectar la presencia de una bacteria que representa un riesgo para la salud pública.",
